  ('education', 1, $json${"$comment":"Education pack (Ch 7.7, Ch 49.5). Content is Proposed (Ch 7.10) until the owner approves it at the 0B.03 checkpoint.","name":{"en":"Education","bn":"শিক্ষা"},"description":{"en":"Schools, colleges, universities, madrasas, coaching and training centres.","bn":"স্কুল, কলেজ, বিশ্ববিদ্যালয়, মাদ্রাসা, কোচিং ও ট্রেনিং প্রতিষ্ঠান।"},"labels":{"after_steps":{"en_singular":"Board flow","en_plural":"Board flows","bn":{"base":"বোর্ড ফ্লো","plural":"বোর্ড ফ্লোগুলো","objective":"বোর্ড ফ্লো","possessive":"বোর্ড ফ্লোর","plural_oblique":"বোর্ড ফ্লোগুলোর"}},"appointment":{"en_singular":"Campus visit","en_plural":"Campus visits","bn":{"base":"ক্যাম্পাস ভিজিট","plural":"ক্যাম্পাস ভিজিটগুলো","objective":"ক্যাম্পাস ভিজিট","possessive":"ক্যাম্পাস ভিজিটের","plural_oblique":"ক্যাম্পাস ভিজিটগুলোর"}},"assessment":{"en_singular":"Admission test","en_plural":"Admission tests","bn":{"base":"ভর্তি পরীক্ষা","plural":"ভর্তি পরীক্ষাগুলো","objective":"ভর্তি পরীক্ষা","possessive":"ভর্তি পরীক্ষার","plural_oblique":"ভর্তি পরীক্ষাগুলোর"}},"board_id":{"en_singular":"Board ID","en_plural":"Board IDs","bn":{"base":"বোর্ড আইডি","plural":"বোর্ড আইডিগুলো","objective":"বোর্ড আইডি","possessive":"বোর্ড আইডির","plural_oblique":"বোর্ড আইডিগুলোর"}},"branch":{"en_singular":"Branch","en_plural":"Branches","bn":{"base":"শাখা","plural":"শাখাগুলো","objective":"শাখা","possessive":"শাখার","plural_oblique":"শাখাগুলোর"}},"caller":{"en_singular":"Caller","en_plural":"Callers","bn":{"base":"কলার","plural":"কলাররা","objective":"কলারকে","possessive":"কলারের","plural_oblique":"কলারদের"}},"client":{"en_singular":"Student","en_plural":"Students","bn":{"base":"শিক্ষার্থী","plural":"শিক্ষার্থীরা","objective":"শিক্ষার্থীকে","possessive":"শিক্ষার্থীর","plural_oblique":"শিক্ষার্থীদের"}},"client_number":{"en_singular":"Student ID","en_plural":"Student IDs","bn":{"base":"শিক্ষার্থী আইডি","plural":"শিক্ষার্থী আইডিগুলো","objective":"শিক্ষার্থী আইডি","possessive":"শিক্ষার্থী আইডির","plural_oblique":"শি